using System;using System.Collections.Generic;
class AttackControllerTest {
 sealed class Fake:IAttackRuntime {public uint Current=0x80000101;public bool Valid=true,Alive=true;public int Starts,Stops,Queries;public uint Target(CharacterRef c){return Current;}public bool ValidTarget(CharacterRef c,uint t){Queries++;return Valid;}public bool Running(CharacterRef c,uint combo,uint t){return Alive;}public AttackResult Start(CharacterRef c,uint t){Starts++;return new AttackResult{Combo=(uint)(100+Starts)};}public AttackResult Stop(CharacterRef c,uint combo,uint t){Stops++;return new AttackResult();}}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static int Main(){try{var primary=new CharacterRef{Pid=1,Id=1,Name="principal"};var a=new CharacterRef{Pid=2,Id=2,Name="secundario"};var b=new CharacterRef{Pid=3,Id=3,Name="outro"};var runtime=new Fake();var c=new AttackController(runtime,new HashSet<int>(),s=>{});c.Tick(primary,new[]{a},true,false,false);Check(runtime.Starts==0,"manual aguarda a tecla");c.Tick(primary,new[]{a},true,false,true);c.Tick(primary,new[]{a},true,false,true);Check(runtime.Starts==1&&c.Engaged(2),"tecla inicia uma macro e nao reinicia sequencia ativa");c.Tick(primary,new[]{a,b},true,false,false);Check(runtime.Starts==2,"somente destinatarios marcados participam");c.Tick(primary,new[]{b},true,false,false);Check(runtime.Stops==1&&!c.Engaged(2)&&c.Engaged(3),"desmarcar um secundario preserva ataque dos demais");runtime.Current=0x80000102;c.Tick(primary,new[]{b},true,false,false);Check(runtime.Stops==2&&runtime.Starts==2,"troca de alvo no modo manual exige nova tecla");c.Tick(primary,new[]{b},true,true,false);Check(runtime.Starts==3,"automatico inicia ao detectar alvo selecionado");c.Tick(primary,new[]{b},true,true,false);Check(runtime.Starts==3,"automatico nao reinicia macro ativa");runtime.Alive=false;c.Tick(primary,new[]{b},true,true,false);c.Tick(primary,new[]{b},true,true,false);Check(runtime.Starts==3&&!c.Engaged(3),"macro terminada nao e reiniciada pelo mesmo alvo");c.Tick(primary,new[]{b},true,false,true);Check(runtime.Starts==4,"nova tecla permite nova sequencia terminada");runtime.Current=0;c.Tick(primary,new[]{b},true,true,false);Check(runtime.Stops==3&&!c.Engaged(3),"perda de alvo encerra ataque gerenciado");runtime.Current=101;c.Tick(primary,new[]{b},true,true,false);Check(runtime.Starts==4,"alvo de jogador nao inicia ataque");runtime.Current=0x80000103;runtime.Valid=false;c.Tick(primary,new[]{b},true,true,false);Check(runtime.Starts==4,"NPC nao atacavel nao inicia macro");c.StopAll();runtime.Valid=true;runtime.Alive=true;c.Tick(primary,new[]{b},true,true,false);c.Tick(primary,new[]{b},false,true,false);Check(runtime.Stops==4&&!c.Engaged(3),"desativar encerra macro sob controle");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
